package com.theprincelive.whatsthat;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.provider.Settings;import android.text.*;import android.view.View;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
MessageStore store; ListView list; TextView countText,emptyText; EditText searchBox; Button open;
@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);store=new MessageStore(this);list=findViewById(R.id.listView);countText=findViewById(R.id.countText);emptyText=findViewById(R.id.emptyText);searchBox=findViewById(R.id.searchBox);open=findViewById(R.id.openBtn);Button clear=findViewById(R.id.clearBtn);open.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)));clear.setOnClickListener(v->{store.clearMessages();load();});searchBox.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){} public void onTextChanged(CharSequence s,int a,int b,int c){load();} public void afterTextChanged(Editable e){}});load();}
@Override protected void onResume(){super.onResume();load();}
boolean enabled(){String s=Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners");return s!=null&&s.contains(getPackageName());}
void load(){open.setVisibility(enabled()?View.GONE:View.VISIBLE);List<SavedMessage> rows=store.getRecentStructured();String q=searchBox.getText().toString().toLowerCase();List<String> out=new ArrayList<>();for(SavedMessage m:rows){String v=m.sender+"\n"+m.body+"\n"+m.time;if(q.isEmpty()||v.toLowerCase().contains(q))out.add(v);}countText.setText(out.size()+" saved items");emptyText.setVisibility(out.isEmpty()?View.VISIBLE:View.GONE);list.setVisibility(out.isEmpty()?View.GONE:View.VISIBLE);list.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,out));}}
